<script setup>
import {ref,onMounted} from 'vue'
import SeoEditor from './SeoEditor.vue'
const props=defineProps({apiWrite:Function})
const data=ref(null),busy=ref(false),error=ref(''),notice=ref(''),paths=ref('')
const integration=ref('')
async function checkConnection(){try{const responses=await Promise.all(['/','/sitemap.xml','/robots.txt'].map(url=>fetch(url,{credentials:'omit',cache:'no-store',signal:AbortSignal.timeout(10000)})));integration.value=responses[0].headers.get('x-nova-seo')&&responses[1].ok&&responses[1].headers.get('content-type')?.includes('xml')&&responses[2].ok&&responses[2].headers.get('content-type')?.includes('text/plain')?'Серверная выдача SEO подключена.':'Серверная выдача SEO ещё не подключена: настройте маршрутизацию на хостинге по инструкции.'}catch{integration.value='Не удалось проверить серверную выдачу SEO. Повторите проверку.'}}
const redirect=ref({source:'',target:'',status:301})
async function load(){data.value=await props.apiWrite('/api/admin/seo','GET');paths.value=data.value.config.disallow.join('\n')}
async function refreshRedirects(){data.value.redirects=(await props.apiWrite('/api/admin/seo','GET')).redirects}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
function save(){run(async()=>{const c={...data.value.config,disallow:paths.value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean)};const result=await props.apiWrite('/api/admin/seo','PUT',{config:c,revision:data.value.revision});data.value={...data.value,...result};notice.value='SEO-настройки сохранены'})}
function add(){run(async()=>{await props.apiWrite('/api/admin/seo/redirects','POST',redirect.value);redirect.value={source:'',target:'',status:301};await refreshRedirects();notice.value='Редирект добавлен'})}
function remove(row){if(confirm('Удалить редирект '+row.source+'?'))run(async()=>{await props.apiWrite('/api/admin/seo/redirects/'+row.id,'DELETE');await refreshRedirects()})}
onMounted(()=>run(async()=>{await load();await checkConnection()}))
</script>
<template><section class="seo-workspace"><div class="page-title"><div><h1>SEO и редиректы</h1><p>Индексация, метатеги, карта сайта и перенаправления.</p></div></div><p v-if="error" class="alert" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><template v-if="data"><section class="panel seo-panel"><h2>Настройки сайта</h2><p v-if="integration" role="status">{{integration}}</p><button class="row-btn" type="button" :disabled="busy" @click="run(checkConnection)">Проверить подключение SEO</button><p>Для исходного HTML, sitemap.xml, robots.txt и HTTP-редиректов веб-сервер должен передавать публичные страницы в NOVA API. <a href="https://github.com/maxx52/nova-engine/blob/main/docs/SEO.md" target="_blank" rel="noopener">Инструкция для хостинга</a>.</p><form @submit.prevent="save"><fieldset :disabled="busy"><label>Основной адрес сайта<input v-model="data.config.site_url" type="url" maxlength="500" placeholder="https://example.ru"><small>Без пути и завершающего слеша. Сейчас используется: {{data.origin}}.</small></label><label>Описание сайта по умолчанию<textarea v-model="data.config.description" maxlength="500" rows="3"></textarea></label><label class="seo-check"><input type="checkbox" v-model="data.config.indexing"> Разрешить индексацию сайта</label><p>Для тестового сайта отключите индексацию. Это не ограничивает доступ к сайту.</p><label>Дополнительные запрещённые пути robots.txt<textarea v-model="paths" rows="5" placeholder="/private&#10;/search"></textarea><small>Один внутренний путь на строку. /admin/ и /api/ исключаются автоматически.</small></label><SeoEditor v-model="data.config.home" title="SEO главной страницы"/><SeoEditor v-model="data.config.catalog" title="SEO каталога"/><SeoEditor v-model="data.config.blog" title="SEO списка статей"/><button class="primary-btn">Сохранить SEO-настройки</button></fieldset></form><div class="seo-links"><a :href="data.origin+'/sitemap.xml'" target="_blank" rel="noopener">sitemap.xml</a><a :href="data.origin+'/robots.txt'" target="_blank" rel="noopener">robots.txt</a></div></section>
<section class="panel seo-panel"><h2>Редиректы</h2><p>Точное совпадение пути; параметры запроса не переносятся. Новое правило не может создавать цикл или затрагивать служебные адреса.</p><form @submit.prevent="add"><fieldset :disabled="busy"><label>Старый адрес<input v-model="redirect.source" required maxlength="2000" placeholder="/old-page"></label><label>Новый адрес<input v-model="redirect.target" required maxlength="2000" placeholder="/new-page"></label><label>Код перенаправления<select v-model.number="redirect.status" aria-label="Код перенаправления"><option :value="301">301 — постоянный</option><option :value="302">302 — временный</option><option :value="307">307 — временный с сохранением метода</option><option :value="308">308 — постоянный с сохранением метода</option></select></label><button class="primary-btn">Добавить редирект</button></fieldset></form><div class="table-wrap"><table><thead><tr><th>Старый адрес</th><th>Новый адрес</th><th>Код</th><th></th></tr></thead><tbody><tr v-for="row in data.redirects" :key="row.id"><td>{{row.source}}</td><td>{{row.target}}</td><td>{{row.status}}</td><td><button class="row-btn danger" :disabled="busy" @click="remove(row)">Удалить</button></td></tr><tr v-if="!data.redirects.length"><td colspan="4">Редиректов пока нет</td></tr></tbody></table></div></section></template></section></template>
<style scoped>
.seo-workspace,.seo-panel,.seo-panel .table-wrap{min-width:0}.seo-panel{padding:24px;display:grid;gap:16px;margin-bottom:24px}.seo-panel form{max-width:760px}.seo-panel fieldset{border:0;padding:0;display:grid;gap:16px;min-width:0}.seo-panel label{display:grid;gap:8px;font-size:13px}.seo-panel input:not([type=checkbox]),.seo-panel textarea,.seo-panel select{width:100%;min-width:0;padding:10px;border:1px solid #cadbd0;border-radius:6px;font:inherit}.seo-check{display:flex!important;align-items:center}.seo-panel p,.seo-panel small{font-size:13px;line-height:1.7;overflow-wrap:anywhere}.seo-panel h2,.seo-panel p{margin:0}.seo-panel .table-wrap{overflow-x:auto}.seo-links{display:flex;gap:20px}
</style>
